 "content": "def transform(grid):
    """Repeat the non-square motif in every panel, using each panel row's color."""
    h, w = len(grid), len(grid[0])
    # Locate full-width/full-height separator lines of the same color.
    row_sep = {r: grid[r][0] for r in range(h)
               if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])}
    col_sep = {c: grid[0][c] for c in range(w)
               if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))}
    sep_colors = set(row_sep.values()) & set(col_sep.values())
    if not sep_colors:
        raise ValueError('No matching full-row/full-column separator color')
    sep = next(iter(sep_colors))
    row_divs = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_divs = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    def intervals(n, divs):
        out, start = [], 0
        for d in divs:
            if start < d:
                out.append((start, d))
            start = d + 1
        if start < n:
            out.append((start, n))
        return out
    row_panels = intervals(h, row_divs)
    col_panels = intervals(w, col_divs)

    # The motif is the densest nonempty panel (the color swatches are smaller).
    panels = []
    for ri, (r0, r1) in enumerate(row_panels):
        for ci, (c0, c1) in enumerate(col_panels):
            cells = [(r-r0, c-c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] not in (0, sep)]
            if cells:
                panels.append((len(cells), ri, ci, r1-r0, c1-c0, cells))
    if not panels:
        raise ValueError('No motif found')
    _, _, _, ph, pw, motif_cells = max(panels, key=lambda x: x[0])
    mask = {(r, c) for r, c, _ in motif_cells}

    # One solid color swatch in the first panel of each panel-row determines
    # the color used for that row's repeated motif.
    row_colors = []
    for r0, r1 in row_panels:
        c0, c1 = col_panels[0]
        counts = {}
        for r in range(r0, r1):
            for c in range(c0, c1):
                v = grid[r][c]
                if v not in (0, sep):
                    counts[v] = counts.get(v, 0) + 1
        if not counts:
            raise ValueError('Missing row color swatch')
        row_colors.append(max(counts, key=counts.get))

    result = [list(row) for row in grid]
    for ri, (r0, r1) in enumerate(row_panels):
        color = row_colors[ri]
        for c0, c1 in col_panels:
            # Clear each panel before stamping the motif in its local coordinates.
            for r in range(r0, r1):
                for c in range(c0, c1):
                    result[r][c] = 0
            for mr, mc in mask:
                if mr < r1-r0 and mc < c1-c0:
                    result[r0+mr][c0+mc] = color
    return result
